writing.practiceCode:
-- PostgreSQL Read Committed; a concurrent transaction commits an update.
BEGIN;
SELECT balance FROM account WHERE id = 7;
-- Concurrent COMMIT occurs here.
SELECT balance FROM account WHERE id = 7;
COMMIT;

recall.code:
BEGIN;
SELECT balance FROM account WHERE id = 1; -- reads 100
-- another transaction commits 50 here
UPDATE account SET balance = 90 WHERE id = 1;
COMMIT;
